// ============================================================================
// DSH peer 依赖类型补充：这些包由 DSH 宿主在运行时提供，本地开发无 node_modules，
// 这里为它们声明最小类型，便于 tsc 通过（运行时以 DSH 提供的为准）。
// ----------------------------------------------------------------------------
// 职责：为宿主导出的依赖（@deepseek-ai/dsh-home-paths 等）补 declare module，
//       让 typecheck 在本地（未安装 peer 包）也能通过；纯类型占位，不实现任何逻辑。
// 与其他模块的关系：宿主半侧（lib/ 下 Cordis 插件）与 client 半侧的编译都依赖
//       这里的声明；新增宿主依赖调用前，必须先在此处补对应 declare module，
//       否则 tsc 报「Cannot find module」。
// 已知坑：
//   - 这里只声明「本插件实际用到的」最小 API 面；真实签名以 DSH 运行时版本为准，
//     宿主升级改变签名后此处可能滞后 —— 遇到运行时类型不符，先对照宿主源码修正声明
// ============================================================================
declare module '@deepseek-ai/dsh-home-paths' {
  /** 解析 DSH 主目录（$DSH_HOME，默认 ~/.dsh） */
  export function resolveDshHome(): string;
}
